import { isHexString, toHex } from "./Hex.js";
import digest from "./utils/digest.js";
import stringToUint8Array from "./utils/stringToUint8Array.js";
export const isHash = (value) => {
    return isHexString(value) && value.length === 64;
};
export const messageToHash = async (message) => {
    return toHex(await digest(stringToUint8Array(message)));
};
